create or replace function public.admin_user_search(p_query text default '') returns jsonb language plpgsql security definer set search_path=public,auth,pg_temp as $$ declare q text:=trim(coalesce(p_query,'')); out jsonb; begin if not exists(select 1 from public.profiles where id=auth.uid() and (is_admin=true or lower(coalesce(role::text,'')) in ('admin','owner','platform_admin','super_admin'))) then raise exception 'admin authorization required'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into out from (select p.id,p.display_name,p.username,p.role,p.subscription_tier,p.is_business_user,p.is_admin,p.created_at,u.email,u.confirmed_at from public.profiles p left join auth.users u on u.id=p.id where q='' or p.display_name ilike '%'||q||'%' or p.username ilike '%'||q||'%' or u.email ilike '%'||q||'%' order by p.created_at desc limit 200) x; return out; end $$; revoke all on function public.admin_user_search(text) from public; grant execute on function public.admin_user_search(text) to authenticated;
create or replace function public.admin_set_user_access(p_target_user_id uuid,p_is_admin boolean default false,p_role text default 'customer',p_subscription_tier text default 'free',p_is_business_user boolean default false,p_reason text default 'Admin access change') returns jsonb language plpgsql security definer set search_path=public,auth,pg_temp as $$ declare old jsonb; newstate jsonb; result jsonb; begin if not exists(select 1 from public.profiles where id=auth.uid() and (is_admin=true or lower(coalesce(role::text,'')) in ('admin','owner','platform_admin','super_admin'))) then raise exception 'admin authorization required'; end if; if p_target_user_id is null then raise exception 'target user required'; end if; if lower(coalesce(p_role,'')) not in ('customer','admin','owner','platform_admin','super_admin') then raise exception 'invalid role'; end if; if lower(coalesce(p_subscription_tier,'')) not in ('free','standard','growth','enterprise','family') then raise exception 'invalid subscription tier'; end if; select to_jsonb(p) into old from public.profiles p where p.id=p_target_user_id for update; if old is null then raise exception 'profile not found'; end if; update public.profiles set is_admin=p_is_admin,is_business_user=p_is_business_user,role=p_role,subscription_tier=p_subscription_tier,updated_at=now() where id=p_target_user_id returning to_jsonb(profiles.*) into result; newstate:=result; insert into public.admin_capability_audit(admin_user_id,target_user_id,previous_state,new_state,reason) values(auth.uid(),p_target_user_id,old,newstate,coalesce(nullif(trim(p_reason),''),'Admin access change')); return result; end $$; revoke all on function public.admin_set_user_access(uuid,boolean,text,text,boolean,text) from public; grant execute on function public.admin_set_user_access(uuid,boolean,text,text,boolean,text) to authenticated;
